-- ----------------------------
-- Function structure for _pgr_array_reverse
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_array_reverse"(anyarray);
CREATE FUNCTION "public"."_pgr_array_reverse"(anyarray)
  RETURNS "pg_catalog"."anyarray" AS $BODY$
SELECT ARRAY(
    SELECT $1[i]
    FROM generate_subscripts($1,1) AS s(i)
    ORDER BY i DESC
);
$BODY$
  LANGUAGE sql IMMUTABLE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_array_reverse"(anyarray) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_array_reverse"(anyarray) IS 'pgRouting internal function';

