-- Function structure for _pgr_checkverttab
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_checkverttab"("vertname" text, "columnsarr" _text, "reporterrs" int4, "fnname" text, OUT "sname" text, OUT "vname" text);
CREATE FUNCTION "public"."_pgr_checkverttab"(IN "vertname" text, IN "columnsarr" _text, IN "reporterrs" int4=1, IN "fnname" text='_pgr_checkVertTab'::text, OUT "sname" text, OUT "vname" text)
  RETURNS "pg_catalog"."record" AS $BODY$
DECLARE
    cname text;
    colname text;
    naming record;
    debuglevel text;
    err  boolean;
    msgKind int;

BEGIN
    msgKind = 0; -- debug_
    execute 'show client_min_messages' into debuglevel;

    perform _pgr_msg(msgKind, fnName, 'Checking table ' || vertname || ' exists');
       select * from _pgr_getTableName(vertname, 0, fnName) into naming;
       sname=naming.sname;
       vname=naming.tname;
       err = sname is NULL or vname is NULL;
    perform _pgr_onError( err, 2, fnName,
          'Vertex Table: ' || vertname || ' not found',
          'Please create ' || vertname || ' using  _pgr_createTopology() or pgr_createVerticesTable()',
          'Vertex Table: ' || vertname || ' found');


    perform _pgr_msg(msgKind, fnName, 'Checking columns of ' || vertname);
      FOREACH cname IN ARRAY columnsArr
      loop
         select _pgr_getcolumnName(vertname, cname, 0, fnName) into colname;
         if colname is null then
           perform _pgr_msg(msgKind, fnName, 'Adding column ' || cname || ' in ' || vertname);
           set client_min_messages  to warning;
                execute 'ALTER TABLE '||_pgr_quote_ident(vertname)||' ADD COLUMN '||cname|| ' integer';
           execute 'set client_min_messages  to '|| debuglevel;
           perform _pgr_msg(msgKind, fnName);
         end if;
      end loop;
    perform _pgr_msg(msgKind, fnName, 'Finished checking columns of ' || vertname);

    perform _pgr_createIndex(vertname , 'id' , 'btree', reportErrs, fnName);
 END
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_checkverttab"("vertname" text, "columnsarr" _text, "reporterrs" int4, "fnname" text, OUT "sname" text, OUT "vname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_checkverttab"("vertname" text, "columnsarr" _text, "reporterrs" int4, "fnname" text, OUT "sname" text, OUT "vname" text) IS 'pgRouting internal function';

