-- ----------------------------
-- Function structure for _pgr_createindex
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_createindex"("tabname" text, "colname" text, "indext" text, "reporterrs" int4, "fnname" text);
CREATE FUNCTION "public"."_pgr_createindex"("tabname" text, "colname" text, "indext" text, "reporterrs" int4=1, "fnname" text='_pgr_createIndex'::text)
  RETURNS "pg_catalog"."void" AS $BODY$
DECLARE
    naming record;
    sname text;
    tname text;

BEGIN
    select * from _pgr_getTableName(tabname, 2, fnName)  into naming;
    sname=naming.sname;
    tname=naming.tname;
    execute _pgr_createIndex(sname, tname, colname, indext, reportErrs, fnName);
END;

$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_createindex"("tabname" text, "colname" text, "indext" text, "reporterrs" int4, "fnname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_createindex"("tabname" text, "colname" text, "indext" text, "reporterrs" int4, "fnname" text) IS 'pgRouting internal function';

-- ----------------------------
-- Function structure for _pgr_createindex
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_createindex"("sname" text, "tname" text, "colname" text, "indext" text, "reporterrs" int4, "fnname" text);
CREATE FUNCTION "public"."_pgr_createindex"("sname" text, "tname" text, "colname" text, "indext" text, "reporterrs" int4=1, "fnname" text='_pgr_createIndex'::text)
  RETURNS "pg_catalog"."void" AS $BODY$
DECLARE
    debuglevel text;
    naming record;
    tabname text;
    query text;
    msgKind int;
BEGIN
  msgKind = 0; -- debug_

  execute 'show client_min_messages' into debuglevel;
  tabname=_pgr_quote_ident(sname||'.'||tname);
  perform _pgr_msg(msgKind, fnName, 'Checking ' || colname || ' column in ' || tabname || ' is indexed');
    IF (_pgr_isColumnIndexed(sname,tname,colname, 0, fnName)) then
       perform _pgr_msg(msgKind, fnName);
    else
      if indext = 'gist' then
        query = 'create  index '||_pgr_quote_ident(tname||'_'||colname||'_idx')||'
                         on '||tabname||' using gist('||quote_ident(colname)||')';
      else
        query = 'create  index '||_pgr_quote_ident(tname||'_'||colname||'_idx')||'
                         on '||tabname||' using btree('||quote_ident(colname)||')';
      end if;
      perform _pgr_msg(msgKind, fnName, 'Adding index ' || tabname || '_' ||  colname || '_idx');
      perform _pgr_msg(msgKind, fnName, ' Using ' ||  query);
      set client_min_messages  to warning;
      BEGIN
        execute query;
        EXCEPTION WHEN others THEN
          perform _pgr_onError( true, reportErrs, fnName,
            'Could not create index on:' || colname, SQLERRM);
      END;
      execute 'set client_min_messages  to '|| debuglevel;
      perform _pgr_msg(msgKind, fnName);
    END IF;
END;

$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_createindex"("sname" text, "tname" text, "colname" text, "indext" text, "reporterrs" int4, "fnname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_createindex"("sname" text, "tname" text, "colname" text, "indext" text, "reporterrs" int4, "fnname" text) IS 'pgRouting internal function';

