-- ----------------------------
-- Function structure for _pgr_dijkstranear
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_dijkstranear"(text, anyarray, int8, int8, "directed" bool, OUT "seq" int4, OUT "path_seq" int4, OUT "start_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8);
