  RETURNS SETOF "pg_catalog"."record" AS $BODY$
    SELECT seq, path_seq, start_vid, node, edge, cost, agg_cost
    FROM _pgr_dijkstra(_pgr_get_statement($1), $2::BIGINT[], ARRAY[$3]::BIGINT[], $5, false, false, $4);
$BODY$
  LANGUAGE sql VOLATILE
  COST 100
