-- ----------------------------
-- Function structure for _pgr_endpoint
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_endpoint"("g" "public"."geometry");
CREATE FUNCTION "public"."_pgr_endpoint"("g" "public"."geometry")
  RETURNS "public"."geometry" AS $BODY$
SELECT CASE WHEN geometryType($1) ~ '^MULTI' THEN ST_EndPoint(st_geometryN($1,1))
ELSE ST_EndPoint($1)
END;
$BODY$
  LANGUAGE sql IMMUTABLE
  COST 100;
ALTER FUNCTION "public"."_pgr_endpoint"("g" "public"."geometry") OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_endpoint"("g" "public"."geometry") IS 'pgRouting internal function';

