-- ----------------------------
-- Function structure for _pgr_get_statement
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_get_statement"("o_sql" text);
CREATE FUNCTION "public"."_pgr_get_statement"("o_sql" text)
  RETURNS "pg_catalog"."text" AS $BODY$
DECLARE
sql TEXT;
BEGIN
    EXECUTE 'SELECT statement FROM pg_prepared_statements WHERE name ='  || quote_literal(o_sql) || ' limit 1 ' INTO sql;
    IF (sql IS NULL) THEN
      RETURN   o_sql;
    ELSE
      RETURN  regexp_replace(regexp_replace(regexp_replace(sql, '\s(as)\s', '___foo___', 'i'), '^.*___foo___', '','i'), ';$', '');
    END IF;
END
$BODY$
  LANGUAGE plpgsql STABLE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_get_statement"("o_sql" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_get_statement"("o_sql" text) IS 'pgRouting internal function';

-- ----------------------------
-- Function structure for _pgr_getcolumnname
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_getcolumnname"("tab" text, "col" text, "reporterrs" int4, "fnname" text);
CREATE FUNCTION "public"."_pgr_getcolumnname"("tab" text, "col" text, "reporterrs" int4=1, "fnname" text='_pgr_getColumnName'::text)
  RETURNS "pg_catalog"."text" AS $BODY$
DECLARE
    sname text;
    tname text;
    cname text;
    naming record;
    err boolean;
BEGIN
    select a.sname, a.tname into naming from _pgr_getTableName(tab,reportErrs, fnName) AS a;
    sname=naming.sname;
    tname=naming.tname;

    select _pgr_getColumnName into cname from _pgr_getColumnName(sname,tname,col,reportErrs, fnName);
    RETURN cname;
END;

$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_getcolumnname"("tab" text, "col" text, "reporterrs" int4, "fnname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_getcolumnname"("tab" text, "col" text, "reporterrs" int4, "fnname" text) IS 'pgRouting internal function';

-- ----------------------------
-- Function structure for _pgr_getcolumnname
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_getcolumnname"("sname" text, "tname" text, "col" text, "reporterrs" int4, "fnname" text);
CREATE FUNCTION "public"."_pgr_getcolumnname"("sname" text, "tname" text, "col" text, "reporterrs" int4=1, "fnname" text='_pgr_getColumnName'::text)
  RETURNS "pg_catalog"."text" AS $BODY$
DECLARE
    cname text;
    naming record;
    err boolean;
BEGIN

    execute 'SELECT column_name FROM information_schema.columns
          WHERE table_name='||quote_literal(tname)||' and table_schema='||quote_literal(sname)||' and column_name='||quote_literal(col) into cname;

    IF cname is null  THEN
    execute 'SELECT column_name FROM information_schema.columns
          WHERE table_name='||quote_literal(tname)||' and table_schema='||quote_literal(sname)||' and column_name='||quote_literal(lower(col))  into cname;
    END if;

    err = cname is null;

    perform _pgr_onError(err, reportErrs, fnName,  'Column '|| col ||' not found', ' Check your column name','Column '|| col || ' found');
    RETURN cname;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_getcolumnname"("sname" text, "tname" text, "col" text, "reporterrs" int4, "fnname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_getcolumnname"("sname" text, "tname" text, "col" text, "reporterrs" int4, "fnname" text) IS 'pgRouting internal function';

-- ----------------------------
-- Function structure for _pgr_getcolumntype
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_getcolumntype"("sname" text, "tname" text, "cname" text, "reporterrs" int4, "fnname" text);
CREATE FUNCTION "public"."_pgr_getcolumntype"("sname" text, "tname" text, "cname" text, "reporterrs" int4=0, "fnname" text='_pgr_getColumnType'::text)
  RETURNS "pg_catalog"."text" AS $BODY$
DECLARE
    ctype text;
    naming record;
    err boolean;
BEGIN

    EXECUTE 'select data_type  from information_schema.columns '
            || 'where table_name = '||quote_literal(tname)
                 || ' and table_schema=' || quote_literal(sname)
                 || ' and column_name='||quote_literal(cname)
       into ctype;
    err = ctype is null;
    perform _pgr_onError(err, reportErrs, fnName,
            'Type of Column '|| cname ||' not found',
            'Check your column name',
            'OK: Type of Column '|| cname || ' is ' || ctype);
    RETURN ctype;
END;

$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_getcolumntype"("sname" text, "tname" text, "cname" text, "reporterrs" int4, "fnname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_getcolumntype"("sname" text, "tname" text, "cname" text, "reporterrs" int4, "fnname" text) IS 'pgRouting internal function';

-- ----------------------------
-- Function structure for _pgr_getcolumntype
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_getcolumntype"("tab" text, "col" text, "reporterrs" int4, "fnname" text);
CREATE FUNCTION "public"."_pgr_getcolumntype"("tab" text, "col" text, "reporterrs" int4=0, "fnname" text='_pgr_getColumnType'::text)
  RETURNS "pg_catalog"."text" AS $BODY$
DECLARE
    sname text;
    tname text;
    cname text;
    ctype text;
    naming record;
    err boolean;
BEGIN

    select * into naming from _pgr_getTableName(tab,reportErrs, fnName) ;
    sname=naming.sname;
    tname=naming.tname;
    select _pgr_getColumnName into cname from _pgr_getColumnName(tab,col,reportErrs, fnName) ;
    select _pgr_getColumnType into ctype from _pgr_getColumnType(sname,tname,cname,reportErrs, fnName);
    RETURN ctype;
END;

$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_getcolumntype"("tab" text, "col" text, "reporterrs" int4, "fnname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_getcolumntype"("tab" text, "col" text, "reporterrs" int4, "fnname" text) IS 'pgRouting internal function';

