-- ----------------------------
-- Function structure for _pgr_iscolumnindexed
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_iscolumnindexed"("tab" text, "col" text, "reporterrs" int4, "fnname" text);
CREATE FUNCTION "public"."_pgr_iscolumnindexed"("tab" text, "col" text, "reporterrs" int4=1, "fnname" text='_pgr_isColumnIndexed'::text)
  RETURNS "pg_catalog"."bool" AS $BODY$
DECLARE
    naming record;
    rec record;
    sname text;
    tname text;
    cname text;
    pkey text;
    value boolean;
BEGIN
    SELECT a.sname, a.tname into naming FROM _pgr_getTableName(tab, 0, fnName) AS a;
    sname=naming.sname;
    tname=naming.tname;
    IF sname IS NULL OR tname IS NULL THEN
        RETURN FALSE;
    END IF;
    SELECT _pgr_getColumnName into cname from _pgr_getColumnName(sname, tname, col, 0, fnName) ;
    IF cname IS NULL THEN
        RETURN FALSE;
    END IF;
    select _pgr_isColumnIndexed into value  from _pgr_isColumnIndexed(sname, tname, cname, reportErrs, fnName);
    return value;
END
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_iscolumnindexed"("tab" text, "col" text, "reporterrs" int4, "fnname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_iscolumnindexed"("tab" text, "col" text, "reporterrs" int4, "fnname" text) IS 'pgRouting internal function';

-- ----------------------------
-- Function structure for _pgr_iscolumnindexed
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_iscolumnindexed"("sname" text, "tname" text, "cname" text, "reporterrs" int4, "fnname" text);
CREATE FUNCTION "public"."_pgr_iscolumnindexed"("sname" text, "tname" text, "cname" text, "reporterrs" int4=1, "fnname" text='_pgr_isColumnIndexed'::text)
  RETURNS "pg_catalog"."bool" AS $BODY$
DECLARE
    naming record;
    rec record;
    pkey text;
BEGIN
    SELECT
          pg_attribute.attname into pkey
         --  format_type(pg_attribute.atttypid, pg_attribute.atttypmod)
          FROM pg_index, pg_class, pg_attribute
          WHERE
                  pg_class.oid = _pgr_quote_ident(sname||'.'||tname)::regclass AND
                  indrelid = pg_class.oid AND
                  pg_attribute.attrelid = pg_class.oid AND
                  pg_attribute.attnum = any(pg_index.indkey)
                  AND indisprimary;

    IF pkey=cname then
          RETURN TRUE;
    END IF;

    SELECT a.index_name,
           b.attname,
           b.attnum,
           a.indisunique,
           a.indisprimary
      INTO rec
      FROM ( SELECT a.indrelid,
                    a.indisunique,
                    a.indisprimary,
                    c.relname index_name,
                    unnest(a.indkey) index_num
               FROM pg_index a,
                    pg_class b,
                    pg_class c,
                    pg_namespace d
              WHERE b.relname=tname
                AND b.relnamespace=d.oid
                AND d.nspname=sname
                AND b.oid=a.indrelid
                AND a.indexrelid=c.oid
           ) a,
           pg_attribute b
     WHERE a.indrelid = b.attrelid
       AND a.index_num = b.attnum
       AND b.attname = cname
  ORDER BY a.index_name,
           a.index_num;

  RETURN FOUND;
  EXCEPTION WHEN OTHERS THEN
    perform _pgr_onError( true, reportErrs, fnName,
    'Error when checking for the postgres system attributes', SQLERR);
    RETURN FALSE;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_iscolumnindexed"("sname" text, "tname" text, "cname" text, "reporterrs" int4, "fnname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_iscolumnindexed"("sname" text, "tname" text, "cname" text, "reporterrs" int4, "fnname" text) IS 'pgRouting internal function';

