-- ----------------------------
-- Function structure for _pgr_msg
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_msg"("msgkind" int4, "fnname" text, "msg" text);
CREATE FUNCTION "public"."_pgr_msg"("msgkind" int4, "fnname" text, "msg" text='---->OK'::text)
  RETURNS "pg_catalog"."void" AS $BODY$
BEGIN
  if msgKind = 0 then
       raise debug '----> PGR DEBUG in %: %',fnName,msg;
  else
       raise notice '----> PGR NOTICE in %: %',fnName,msg;
  end if;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_msg"("msgkind" int4, "fnname" text, "msg" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_msg"("msgkind" int4, "fnname" text, "msg" text) IS 'pgRouting internal function';

-- ----------------------------
-- Function structure for _pgr_onerror
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_onerror"("errcond" bool, "reporterrs" int4, "fnname" text, "msgerr" text, "hinto" text, "msgok" text);
CREATE FUNCTION "public"."_pgr_onerror"("errcond" bool, "reporterrs" int4, "fnname" text, "msgerr" text, "hinto" text='No hint'::text, "msgok" text='OK'::text)
  RETURNS "pg_catalog"."void" AS $BODY$
BEGIN
  if errCond=true then
     if reportErrs=0 then
       raise debug '----> PGR DEBUG in %: %',fnName,msgerr USING HINT = '  ---->'|| hinto;
     else
       if reportErrs = 2 then
         raise notice '----> PGR ERROR in %: %',fnName,msgerr USING HINT = '  ---->'|| hinto;
         raise raise_exception;
       else
         raise notice '----> PGR NOTICE in %: %',fnName,msgerr USING HINT = '  ---->'|| hinto;
       end if;
     end if;
  else
       raise debug 'PGR ----> %: %',fnName,msgok;
  end if;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_onerror"("errcond" bool, "reporterrs" int4, "fnname" text, "msgerr" text, "hinto" text, "msgok" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_onerror"("errcond" bool, "reporterrs" int4, "fnname" text, "msgerr" text, "hinto" text, "msgok" text) IS 'pgRouting internal function';

