-- ----------------------------
-- Function structure for _pgr_pointtoid
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_pointtoid"("point" "public"."geometry", "tolerance" float8, "vertname" text, "srid" int4);
CREATE FUNCTION "public"."_pgr_pointtoid"("point" "public"."geometry", "tolerance" float8, "vertname" text, "srid" int4)
  RETURNS "pg_catalog"."int8" AS $BODY$
DECLARE
    rec record;
    pid bigint;

BEGIN
    EXECUTE 'SELECT ST_Distance(
        the_geom,
        ST_GeomFromText(ST_AsText('
                || quote_literal(point::text)
                || '),'
            || srid ||')) AS d, id, the_geom
    FROM '||_pgr_quote_ident(vertname)||'
    WHERE ST_DWithin(
        the_geom,
        ST_GeomFromText(
            ST_AsText(' || quote_literal(point::text) ||'),
            ' || srid || '),' || tolerance||')
    ORDER BY d
    LIMIT 1' INTO rec ;
    IF rec.id IS NOT NULL THEN
        pid := rec.id;
    ELSE
        execute 'INSERT INTO '||_pgr_quote_ident(vertname)||' (the_geom) VALUES ('||quote_literal(point::text)||')';
        pid := lastval();
END IF;

RETURN pid;

END;
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100;
ALTER FUNCTION "public"."_pgr_pointtoid"("point" "public"."geometry", "tolerance" float8, "vertname" text, "srid" int4) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_pointtoid"("point" "public"."geometry", "tolerance" float8, "vertname" text, "srid" int4) IS 'pgRouting internal function';

