-- ----------------------------
-- Function structure for _pgr_quote_ident
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_quote_ident"("idname" text);
CREATE FUNCTION "public"."_pgr_quote_ident"("idname" text)
  RETURNS "pg_catalog"."text" AS $BODY$
declare
    t text[];
    pgver text;

begin
    pgver := regexp_replace(version(), E'^PostgreSQL ([^ ]+)[ ,].*$', E'\\1');

    if _pgr_versionless(pgver, '9.2') then
        select into t array_agg(quote_ident(term)) from
            (select nullif(unnest, '') as term
               from unnest(string_to_array(idname, '.'))) as foo;
    else
        select into t array_agg(quote_ident(term)) from
            (select unnest(string_to_array(idname, '.', '')) as term) as foo;
    end if;
    return array_to_string(t, '.');
end;
$BODY$
  LANGUAGE plpgsql IMMUTABLE
  COST 100;
ALTER FUNCTION "public"."_pgr_quote_ident"("idname" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_quote_ident"("idname" text) IS 'pgRouting internal function';

