-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_startpoint"("g" "public"."geometry");
CREATE FUNCTION "public"."_pgr_startpoint"("g" "public"."geometry")
  RETURNS "public"."geometry" AS $BODY$
SELECT CASE WHEN geometryType($1) ~ '^MULTI' THEN ST_StartPoint(ST_geometryN($1,1))
ELSE ST_StartPoint($1)
END;
$BODY$
  LANGUAGE sql IMMUTABLE
  COST 100;
