-- ----------------------------
-- Function structure for _pgr_trspviavertices
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_trspviavertices"("sql" text, "vids" _int4, "directed" bool, "has_rcost" bool, "turn_restrict_sql" text, OUT "seq" int4, OUT "id1" int4, OUT "id2" int4, OUT "id3" int4, OUT "cost" float8);
CREATE FUNCTION "public"."_pgr_trspviavertices"(IN "sql" text, IN "vids" _int4, IN "directed" bool, IN "has_rcost" bool, IN "turn_restrict_sql" text=NULL::text, OUT "seq" int4, OUT "id1" int4, OUT "id2" int4, OUT "id3" int4, OUT "cost" float8)
  RETURNS SETOF "pg_catalog"."record" AS $BODY$

declare
    i integer;
    rr RECORD;
    lrr RECORD;
    lrra boolean := false;
    seq1 integer := 0;
    seq2 integer := 0;
    restrictions_query TEXT;

begin
    IF (turn_restrict_sql IS NULL) THEN
        RAISE EXCEPTION 'Restrictions Missing';
    END IF;

    restrictions_query = $$
    WITH old_restrictions AS ( $$ ||
        $5 || $$
    )
    SELECT ROW_NUMBER() OVER() AS id,
    _pgr_array_reverse(array_prepend(target_id, string_to_array(via_path, ',')::INTEGER[])) AS path,
    to_cost AS cost
    FROM old_restrictions;
    $$;


    -- loop through each pair of vids and compute the path
    for i in 1 .. array_length(vids, 1)-1 loop
        seq2 := seq2 + 1;
        for rr in select a.seq, seq2 as id1, a.node::INTEGER as id2, a.edge::INTEGER as id3, a.cost
                    from _pgr_trsp(sql, restrictions_query, vids[i], vids[i+1], directed) as a loop
            -- filter out the individual path ends except the last one
            -- we might not want to do this so we can know where the via points are in the path result
            -- but this needs more thought
            --raise notice 'rr: %', rr;
            if rr.id3 = -1 then
                lrr := rr;
                lrra := true;
            else
                seq1 := seq1 + 1;
                rr.seq := seq1;

                seq := rr.seq;
                id1 := rr.id1;
                id2 := rr.id2;
                id3 := rr.id3;
                cost := rr.cost;
                return next;
            end if;
        end loop;
    end loop;

    if lrra then
        seq1 := seq1 + 1;
        lrr.seq := seq1;

        seq := lrr.seq;
        id1 := lrr.id1;
        id2 := lrr.id2;
        id3 := lrr.id3;
        cost := lrr.cost;
        return next;
    end if;
    return;
end;
$BODY$
  LANGUAGE plpgsql STABLE
  COST 100
  ROWS 1000;
ALTER FUNCTION "public"."_pgr_trspviavertices"("sql" text, "vids" _int4, "directed" bool, "has_rcost" bool, "turn_restrict_sql" text, OUT "seq" int4, OUT "id1" int4, OUT "id2" int4, OUT "id3" int4, OUT "cost" float8) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_trspviavertices"("sql" text, "vids" _int4, "directed" bool, "has_rcost" bool, "turn_restrict_sql" text, OUT "seq" int4, OUT "id1" int4, OUT "id2" int4, OUT "id3" int4, OUT "cost" float8) IS 'pgRouting internal function deprecated on v3.4.0';

