-- ----------------------------
-- Function structure for _pgr_versionless
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_versionless"("v1" text, "v2" text);
CREATE FUNCTION "public"."_pgr_versionless"("v1" text, "v2" text)
  RETURNS "pg_catalog"."bool" AS $BODY$


declare
    v1a text[];
    v2a text[];
    nv1 integer;
    nv2 integer;
    ne1 integer;
    ne2 integer;

begin
    -- separate components into an array, like:
    -- '2.1.0-beta3dev'  =>  {2,1,0,beta3dev}
    v1a := regexp_matches(v1, E'^(\\d+)(?:[\\.](\\d+))?(?:[\\.](\\d+))?[-+\\.]?(.*)$');
    v2a := regexp_matches(v2, E'^(\\d+)(?:[\\.](\\d+))?(?:[\\.](\\d+))?[-+\\.]?(.*)$');

    -- convert modifiers to numbers for comparison
    -- we do not delineate between alpha1, alpha2, alpha3, etc
    ne1 := case when v1a[4] is null or v1a[4]='' then 5
                when v1a[4] ilike 'rc%' then 4
                when v1a[4] ilike 'beta%' then 3
                when v1a[4] ilike 'alpha%' then 2
                when v1a[4] ilike 'dev%' then 1
                else 0 end;

    ne2 := case when v2a[4] is null or v2a[4]='' then 5
                when v2a[4] ilike 'rc%' then 4
                when v2a[4] ilike 'beta%' then 3
                when v2a[4] ilike 'alpha%' then 2
                when v2a[4] ilike 'dev%' then 1
                else 0 end;

    nv1 := v1a[1]::integer * 10000 +
           coalesce(v1a[2], '0')::integer * 1000 +
           coalesce(v1a[3], '0')::integer *  100 + ne1;
    nv2 := v2a[1]::integer * 10000 +
           coalesce(v2a[2], '0')::integer * 1000 +
           coalesce(v2a[3], '0')::integer *  100 + ne2;

    --raise notice 'nv1: %, nv2: %, ne1: %, ne2: %', nv1, nv2, ne1, ne2;

    return nv1 < nv2;
end;
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 1;
ALTER FUNCTION "public"."_pgr_versionless"("v1" text, "v2" text) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_versionless"("v1" text, "v2" text) IS 'pgRouting internal function';

-- ----------------------------
-- Function structure for _pgr_vrponedepot
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."_pgr_vrponedepot"(text, text, text, int4, OUT "seq" int4, OUT "vehicle_seq" int4, OUT "vehicle_id" int8, OUT "stop_seq" int4, OUT "stop_type" int4, OUT "stop_id" int8, OUT "order_id" int8, OUT "cargo" float8, OUT "travel_time" float8, OUT "arrival_time" float8, OUT "wait_time" float8, OUT "service_time" float8, OUT "departure_time" float8);
CREATE FUNCTION "public"."_pgr_vrponedepot"(IN text, IN text, IN text, IN int4, OUT "seq" int4, OUT "vehicle_seq" int4, OUT "vehicle_id" int8, OUT "stop_seq" int4, OUT "stop_type" int4, OUT "stop_id" int8, OUT "order_id" int8, OUT "cargo" float8, OUT "travel_time" float8, OUT "arrival_time" float8, OUT "wait_time" float8, OUT "service_time" float8, OUT "departure_time" float8)
  RETURNS SETOF "pg_catalog"."record" AS $BODY$
DECLARE
orders_sql TEXT;
trucks_sql TEXT;
matrix_sql TEXT;
final_sql TEXT;
BEGIN

    orders_sql = $$WITH
    vrp_orders AS ($$ || $1 || $$ ),
    pickups AS (
        SELECT id, x AS p_x, y AS p_y, open_time AS p_open, close_time AS p_close, service_time AS p_service
        FROM vrp_orders
        WHERE id = $$ || $4 || $$
    )
    SELECT vrp_orders.id AS id, order_unit AS demand, pickups.id AS p_node_id, p_x, p_y, p_open, p_close, p_service,
    vrp_orders.id AS d_node_id, x AS d_x, y AS d_y, open_time AS d_open, close_time AS d_close, service_time AS d_service
    FROM vrp_orders, pickups
    WHERE vrp_orders.id != $$ || $4;


    trucks_sql = $$ WITH
    vrp_orders AS ($$ || $1 || $$ ),
    vrp_vehicles AS ($$ || $2 || $$ ),
    starts AS (
        SELECT id AS start_node_id, x AS start_x, y AS start_y, open_time AS start_open, close_time AS start_close, service_time AS start_service
        FROM vrp_orders
        WHERE id = $$ || $4 || $$
    )
    SELECT vehicle_id AS id, capacity, starts.* FROM vrp_vehicles, starts;
    $$;

    final_sql = '
    SELECT seq, vehicle_seq, vehicle_id, stop_seq, stop_type, stop_id, order_id, cargo, travel_time, arrival_time,
           wait_time, service_time, departure_time
    FROM _pgr_pickDeliver(
            $$' || orders_sql || '$$,
            $$' || trucks_sql || '$$,
            $$' || $3 || '$$,
            max_cycles := 3,
            initial_sol := 7 ); ';

    RAISE DEBUG '%', orders_sql;
    RAISE DEBUG '%', trucks_sql;
    RAISE DEBUG '%', $3;
    RAISE DEBUG '%', final_sql;

    RETURN QUERY EXECUTE final_sql;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100
  ROWS 1000;
ALTER FUNCTION "public"."_pgr_vrponedepot"(text, text, text, int4, OUT "seq" int4, OUT "vehicle_seq" int4, OUT "vehicle_id" int8, OUT "stop_seq" int4, OUT "stop_type" int4, OUT "stop_id" int8, OUT "order_id" int8, OUT "cargo" float8, OUT "travel_time" float8, OUT "arrival_time" float8, OUT "wait_time" float8, OUT "service_time" float8, OUT "departure_time" float8) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."_pgr_vrponedepot"(text, text, text, int4, OUT "seq" int4, OUT "vehicle_seq" int4, OUT "vehicle_id" int8, OUT "stop_seq" int4, OUT "stop_type" int4, OUT "stop_id" int8, OUT "order_id" int8, OUT "cargo" float8, OUT "travel_time" float8, OUT "arrival_time" float8, OUT "wait_time" float8, OUT "service_time" float8, OUT "departure_time" float8) IS 'pgRouting internal function';

