DROP FUNCTION IF EXISTS "public"."pgr_astarcost"(text, text, "directed" bool, "heuristic" int4, "factor" float8, "epsilon" float8, OUT "start_vid" int8, OUT "end_vid" int8, OUT "agg_cost" float8);
CREATE FUNCTION "public"."pgr_astarcost"(IN text, IN text, IN "directed" bool=true, IN "heuristic" int4=5, IN "factor" float8=1.0, IN "epsilon" float8=1.0, OUT "start_vid" int8, OUT "end_vid" int8, OUT "agg_cost" float8)
