-- ----------------------------
-- Function structure for pgr_breadthfirstsearch
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."pgr_breadthfirstsearch"(text, anyarray, "max_depth" int8, "directed" bool, OUT "seq" int8, OUT "depth" int8, OUT "start_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8);
CREATE FUNCTION "public"."pgr_breadthfirstsearch"(IN text, IN anyarray, IN "max_depth" int8='9223372036854775807'::bigint, IN "directed" bool=true, OUT "seq" int8, OUT "depth" int8, OUT "start_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8)
  RETURNS SETOF "pg_catalog"."record" AS $BODY$
BEGIN
    IF $3 < 0 THEN
        RAISE EXCEPTION 'Negative value found on ''max_depth'''
        USING HINT = format('Value found: %s', $3);
    END IF;


    RETURN QUERY
    SELECT a.seq, a.depth, a.start_vid, a.node, a.edge, a.cost, a.agg_cost
    FROM _pgr_breadthFirstSearch(_pgr_get_statement($1), $2::BIGINT[], max_depth, directed) AS a;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100
  ROWS 1000;
ALTER FUNCTION "public"."pgr_breadthfirstsearch"(text, anyarray, "max_depth" int8, "directed" bool, OUT "seq" int8, OUT "depth" int8, OUT "start_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8) OWNER TO "postgres";
