DROP FUNCTION IF EXISTS "public"."pgr_depthfirstsearch"(text, anyarray, "directed" bool, "max_depth" int8, OUT "seq" int8, OUT "depth" int8, OUT "start_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8);
CREATE FUNCTION "public"."pgr_depthfirstsearch"(IN text, IN anyarray, IN "directed" bool=true, IN "max_depth" int8='9223372036854775807'::bigint, OUT "seq" int8, OUT "depth" int8, OUT "start_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8)
  RETURNS SETOF "pg_catalog"."record" AS $BODY$
BEGIN
    IF $4 < 0 THEN
        RAISE EXCEPTION 'Negative value found on ''max_depth'''
        USING HINT = format('Value found: %s', $4);
    END IF;


    RETURN QUERY
    SELECT a.seq, a.depth, a.start_vid, a.node, a.edge, a.cost, a.agg_cost
    FROM _pgr_depthFirstSearch(_pgr_get_statement($1), $2, directed, max_depth) AS a;
END;
