DROP FUNCTION IF EXISTS "public"."pgr_hawickcircuits"(text, OUT "seq" int4, OUT "path_id" int4, OUT "path_seq" int4, OUT "start_vid" int8, OUT "end_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8);
CREATE FUNCTION "public"."pgr_hawickcircuits"(IN text, OUT "seq" int4, OUT "path_id" int4, OUT "path_seq" int4, OUT "start_vid" int8, OUT "end_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8)
  RETURNS SETOF "pg_catalog"."record" AS $BODY$
BEGIN
    RETURN QUERY
    SELECT a.seq, a.path_id, a.path_seq, a.start_vid, a.end_vid, a.node, a.edge, a.cost, a.agg_cost
    FROM _pgr_hawickCircuits(_pgr_get_statement($1)) AS a;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100
  ROWS 1000;
