-- ----------------------------
-- Function structure for pgr_kruskalbfs
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."pgr_kruskalbfs"(text, int8, "max_depth" int8, OUT "seq" int8, OUT "depth" int8, OUT "start_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8);
CREATE FUNCTION "public"."pgr_kruskalbfs"(IN text, IN int8, IN "max_depth" int8='9223372036854775807'::bigint, OUT "seq" int8, OUT "depth" int8, OUT "start_vid" int8, OUT "node" int8, OUT "edge" int8, OUT "cost" float8, OUT "agg_cost" float8)
  RETURNS SETOF "pg_catalog"."record" AS $BODY$
BEGIN
    IF $3 < 0 THEN
        RAISE EXCEPTION 'Negative value found on ''max_depth'''
        USING HINT = format('Value found: %s', $3);
    END IF;


    RETURN QUERY
    SELECT a.seq, a.depth, a.start_vid, a.node, a.edge, a.cost, a.agg_cost
    FROM _pgr_kruskal(_pgr_get_statement($1), ARRAY[$2]::BIGINT[], 'BFS', $3, -1) AS a;
END;
$BODY$
  LANGUAGE plpgsql VOLATILE STRICT
  COST 100
