DROP FUNCTION IF EXISTS "public"."pgr_pickdeliver"(text, text, text, "factor" float8, "max_cycles" int4, "initial_sol" int4, OUT "seq" int4, OUT "vehicle_seq" int4, OUT "vehicle_id" int8, OUT "stop_seq" int4, OUT "stop_type" int4, OUT "stop_id" int8, OUT "order_id" int8, OUT "cargo" float8, OUT "travel_time" float8, OUT "arrival_time" float8, OUT "wait_time" float8, OUT "service_time" float8, OUT "departure_time" float8);
CREATE FUNCTION "public"."pgr_pickdeliver"(IN text, IN text, IN text, IN "factor" float8=1, IN "max_cycles" int4=10, IN "initial_sol" int4=4, OUT "seq" int4, OUT "vehicle_seq" int4, OUT "vehicle_id" int8, OUT "stop_seq" int4, OUT "stop_type" int4, OUT "stop_id" int8, OUT "order_id" int8, OUT "cargo" float8, OUT "travel_time" float8, OUT "arrival_time" float8, OUT "wait_time" float8, OUT "service_time" float8, OUT "departure_time" float8)
  RETURNS SETOF "pg_catalog"."record" AS $BODY$
    SELECT seq, vehicle_seq, vehicle_id, stop_seq, stop_type, stop_id, order_id, cargo, travel_time, arrival_time,
           wait_time, service_time, departure_time
    FROM _pgr_pickDeliver(_pgr_get_statement($1), _pgr_get_statement($2), $3, $4, $5);
$BODY$
  LANGUAGE sql VOLATILE STRICT
  COST 100
  ROWS 1000;
ALTER FUNCTION "public"."pgr_pickdeliver"(text, text, text, "factor" float8, "max_cycles" int4, "initial_sol" int4, OUT "seq" int4, OUT "vehicle_seq" int4, OUT "vehicle_id" int8, OUT "stop_seq" int4, OUT "stop_type" int4, OUT "stop_id" int8, OUT "order_id" int8, OUT "cargo" float8, OUT "travel_time" float8, OUT "arrival_time" float8, OUT "wait_time" float8, OUT "service_time" float8, OUT "departure_time" float8) OWNER TO "postgres";
COMMENT ON FUNCTION "public"."pgr_pickdeliver"(text, text, text, "factor" float8, "max_cycles" int4, "initial_sol" int4, OUT "seq" int4, OUT "vehicle_seq" int4, OUT "vehicle_id" int8, OUT "stop_seq" int4, OUT "stop_type" int4, OUT "stop_id" int8, OUT "order_id" int8, OUT "cargo" float8, OUT "travel_time" float8, OUT "arrival_time" float8, OUT "wait_time" float8, OUT "service_time" float8, OUT "departure_time" float8) IS 'pgr_pickDeliver
 - EXPERIMENTAL
 - Parameters:
   - orders SQL with columns:
     - id, demand, p_node_id, p_open, p_close, d_node_id, d_open, d_close
     - optional columns:
        - p_service := 0
        - d_service := 0
   - vehicles SQL with columns:
     - id, capacity, start_open, start_close
     - optional columns:
        - speed := 1
        - start_service := 0
        - end_open := start_open
        - end_close := start_close
        - end_service := 0
   - Matrix
     - start_vid
     - end_vid
     - agg_cost
 - Optional Parameters:
   - factor: default := 1
   - max_cycles: default := 10
   - initial_sol: default := 4
- Documentation:
   - https://docs.pgrouting.org/latest/en/pgr_pickDeliver.html
';

