-- ----------------------------
-- Function structure for pgr_prim
-- ----------------------------
DROP FUNCTION IF EXISTS "public"."pgr_prim"(text, OUT "edge" int8, OUT "cost" float8);
CREATE FUNCTION "public"."pgr_prim"(IN text, OUT "edge" int8, OUT "cost" float8)
  RETURNS SETOF "pg_catalog"."record" AS $BODY$
    SELECT edge, cost
    FROM _pgr_prim(_pgr_get_statement($1), ARRAY[0]::BIGINT[], '', -1, -1);
$BODY$
  LANGUAGE sql VOLATILE STRICT
  COST 100
